import java.util.*;

public class Main {
    static int evalFlat(String expr) {                    // evaluate an expression with no parentheses at all
        int result = 0, num = 0, sign = 1;
        for (char ch : (expr + "+").toCharArray()) {       // a trailing "+" flushes the very last number
            if (Character.isDigit(ch)) {
                num = num * 10 + (ch - '0');
            } else if (ch == '+' || ch == '-') {
                result += sign * num;                          // apply the previous sign to the number just read
                num = 0;
                sign = ch == '+' ? 1 : -1;
            }
        }
        return result;
    }

    static int calculate(String s) {
        while (s.contains("(")) {
            int close = s.indexOf(')');                      // the first closing parenthesis found
            int open = s.lastIndexOf('(', close);              // its matching opening parenthesis, just before it
            int innerValue = evalFlat(s.substring(open + 1, close));  // evaluate only what is inside this pair
            s = s.substring(0, open) + innerValue + s.substring(close + 1);  // splice the value back in
        }
        return evalFlat(s);                                 // no parentheses left, evaluate what remains
    }

    public static void main(String[] args) {
        String s = "(1+(4+5+2)-3)";
        System.out.println(calculate(s));
    }
}

