import java.util.*;

public class Main {
    static int calculate(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        int result = 0, num = 0, sign = 1;
        for (char ch : s.toCharArray()) {
            if (Character.isDigit(ch)) {
                num = num * 10 + (ch - '0');
            } else if (ch == '+' || ch == '-') {
                result += sign * num;                          // apply the previous sign to the number just read
                num = 0;
                sign = ch == '+' ? 1 : -1;
            } else if (ch == '(') {
                stack.push(result);                             // remember the result built up so far
                stack.push(sign);                               // remember the sign this whole group carries
                result = 0;
                sign = 1;
            } else if (ch == ')') {
                result += sign * num;                           // finish the number just before this closing bracket
                num = 0;
                result *= stack.pop();                           // apply the sign the group carried in from outside
                result += stack.pop();                            // add back the result from before the group started
            }
        }
        result += sign * num;                                 // flush whatever number the expression ends on
        return result;
    }

    public static void main(String[] args) {
        String s = "(1+(2))";
        System.out.println(calculate(s));
    }
}

